193	function triggerStoryStats(): void {
194	  const items = Array.from(
195	    document.querySelectorAll<HTMLElement>(STORY_STAT_SELECTOR),
196	  );
197	  if (!items.length) return;
198	
199	  items.forEach((el, i) => {
200	    const target = Number(el.dataset.countTo ?? 0);
201	    let startTime: number | null = null;
202	
203	    function tick(ts: number): void {
204	      if (startTime === null) startTime = ts;
205	      const t = Math.min((ts - startTime) / STORY_STAT_DURATION, 1);
206	      const eased = 1 - Math.pow(1 - t, 3);
207	      el.textContent = Math.round(eased * target).toString();
208	      if (t < 1) requestAnimationFrame(tick);
209	    }
210	
211	    window.setTimeout(() => requestAnimationFrame(tick), i * STORY_STAT_STAGGER);
212	  });
213	}
