24	class CombustionSim {
25	  private elapsed = 0;
26	  private phase = 0;
27	  private surgeTimer = 0;
28	  private nextBurst = 0.05;
29	  private surgeAmp = 0;
30	  private riseLen = 0;
31	  private fallLen = 0;
32	  private smoothLen = 0.78;
33	
34	  constructor(
35	    private cfg: JetEngineResolvedConfig,
36	    private easeOutExpo: EaseFn,
37	    private easeOutCubic: EaseFn,
38	  ) {}
39	
40	  applyConfig(cfg: JetEngineResolvedConfig): void {
41	    this.cfg = cfg;
42	  }
43	
44	  update(dt: number): { flameLen: number; throttle: number; elapsed: number } {
45	    const c = this.cfg;
46	    const spd = Math.max(0.01, c.burstSpeed);
47	    const base = c.baseIdle;
48	
49	    this.elapsed += dt;
50	    this.surgeTimer += dt;
51	
52	    const breath =
53	      0.04 * Math.sin(this.elapsed * 6.0 * spd) +
54	      0.02 * Math.sin(this.elapsed * 11.0 * spd);
55	    let target = base + breath;
56	
57	    if (this.phase === 0 && this.surgeTimer >= this.nextBurst) {
58	      this.phase = 1;
59	      this.surgeTimer = 0;
60	      this.riseLen = (0.02 + Math.random() * 0.04) / spd;
61	      this.surgeAmp =
62	        base + c.burstAmpMin + Math.random() * (c.burstAmpMax - c.burstAmpMin);
63	    }
64	
65	    if (this.phase === 1) {
66	      const p = Math.min(this.surgeTimer / this.riseLen, 1);
67	      target = base + this.easeOutExpo(p) * (this.surgeAmp - base);
68	      if (p >= 1) {
69	        this.phase = 2;
70	        this.surgeTimer = 0;
71	        this.fallLen = (0.05 + Math.random() * 0.12) / spd;
72	      }
73	    } else if (this.phase === 2) {
74	      const p = Math.min(this.surgeTimer / this.fallLen, 1);
75	      target = base + this.easeOutCubic(1 - p) * (this.surgeAmp - base);
76	      if (p >= 1) {
