608	    const fragment = document.createDocumentFragment();
609	    const markerCount = INTRO_ACTION_COUNTDOWN_ORBIT.markerCount;
610	    const loopDuration =
611	      INTRO_ACTION_COUNTDOWN_SEQUENCE.enterDuration +
612	      INTRO_ACTION_COUNTDOWN_SEQUENCE.holdDuration +
613	      INTRO_ACTION_COUNTDOWN_SEQUENCE.exitDuration +
614	      INTRO_ACTION_COUNTDOWN_SEQUENCE.gapDuration;
615	    const delayStep = loopDuration / markerCount;
616	
617	    for (let index = 0; index < markerCount; index += 1) {
618	      const progress = index / markerCount;
619	      const perimeterProgress = progress * 4;
620	      const side = Math.floor(perimeterProgress) % 4;
621	      const ratio = perimeterProgress - Math.floor(perimeterProgress);
622	      let x = 0;
623	      let y = 0;
624	
625	      if (side === 0) {
626	        x = ratio;
627	        y = 0;
628	      } else if (side === 1) {
629	        x = 1;
630	        y = ratio;
631	      } else if (side === 2) {
632	        x = 1 - ratio;
633	        y = 1;
634	      } else {
635	        x = 0;
636	        y = 1 - ratio;
637	      }
638	
